 "content": "from collections import Counter


def transform(grid):
    """Mark vertical breaks between aligned segments of the same foreground color."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color = grid[r][c]
            end = r
            while end + 1 < h and grid[end + 1][c] == color:
                end += 1
            nxt = end + 1
            while nxt < h and grid[nxt][c] == bg:
                nxt += 1
            if nxt < h and nxt > end + 1 and grid[nxt][c] == color:
                for rr in range(end + 1, nxt):
                    out[rr][c] = 4
                r = nxt
            else:
                r = end + 1
    return out
